static int32_t __stdcall SKILLDESC_CalcStatGroupValue(D2UnitStrc * pUnit, eD2UnitStat eStat, int32_t nStatValue, D2ItemStatCostTxt * pItemStatCostTxt) {
    D2UnitStrc* pPlayerUnit_lcl;
    int nRawStatValue;
    D2ItemStatCostTxt* pStatCostLine;
    uint16_t nLayer;
    if (pItemStatCostTxt->op >= 2 && pItemStatCostTxt->op <= 5) {
      eD2UnitStat eUnitStat;
      eUnitStat = (eD2UnitStat)pItemStatCostTxt->opBase;
      if ((int)eUnitStat >= sgptDataTable->nTxtItemStatCostSize) {
        return 0;
      }

      pStatCostLine = sgptDataTable->pTxtItemStatCost + eUnitStat;
      if (!pStatCostLine) {
        return 0;
      }

      nLayer = 0;
      pPlayerUnit_lcl = UNIT::Player::GetPlayerUnit_UI();
      nRawStatValue = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pPlayerUnit_lcl, eUnitStat, nLayer);
      nStatValue = (nRawStatValue >> (pStatCostLine->valshift & 0x1fU)) * nStatValue >> (pItemStatCostTxt->opParam & 0x1f);
    }

    int32_t nShiftedValue = nStatValue >> (pItemStatCostTxt->valshift & 0x1fU);
    if (!(eStat == UNITSTAT_item_undeaddamage_percent && pUnit && pUnit->eUnitType == UNIT_ITEM)) {
      return nShiftedValue;
    }

    uint32_t nBluntBonus = D2Common::ITEMS::Items::ITEMS_IsA(pUnit, ITEMTYPE_Blunt);
    if (!nBluntBonus) {
      return nShiftedValue;
    }

    nShiftedValue += 0x32;
    return nShiftedValue;
}

BOOL __stdcall SKILLDESC_CalcStatGroupMinMax(D2UnitStrc * pUnit, D2StatListExStrc * pStatList, eD2UnitStat eUnitStat, int32_t nGroupValue, D2ItemStatCostTxt * pItemStatCostTxt, BOOL * pbIsFirstInGroup) {
    int nIterStatValue;
    int32_t nCalcGroupValue;
    if (!pItemStatCostTxt->dgrp) {
      return 0;
    }

    int32_t nStatId = sgptDataTable->nTxtItemStatCostSize - 1;
    if (-1 >= nStatId) {
      return 1;
    }

    int nStatCostByteOffset = nStatId * 0x144;
    D2DataTableTxtStrc* pDataTableLocal = sgptDataTable;
    do {
      D2ItemStatCostTxt* pStatCostEntry;
      if (nStatId >= pDataTableLocal->nTxtItemStatCostSize) {
        return 0;
      }

      pStatCostEntry = (D2ItemStatCostTxt*)(pDataTableLocal->pTxtItemStatCost->saveBits + nStatCostByteOffset - 0x19);
      if (!pStatCostEntry) {
        return 0;
      }
      if (pItemStatCostTxt->dgrp == pStatCostEntry->dgrp) {
        *pbIsFirstInGroup = (uint32_t)(nStatId == eUnitStat);
        nIterStatValue = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, nStatId, 0);
        nCalcGroupValue = SKILLDESC_CalcStatGroupValue(pUnit, nStatId, nIterStatValue, pStatCostEntry);
        pDataTableLocal = sgptDataTable;
        if (nGroupValue != nCalcGroupValue) {
          return 0;
        }
      }

      nStatId -= UNITSTAT_energy;
      nStatCostByteOffset += -0x144;
    } while (nStatId >= 0);

    return 1;
}

