int32_t __stdcall SKILLDESC_GetAuraBonusDamage() {
    D2StatListExStrc* pStatList;
    eD2Skills eSkill;
    int nStateCount;
    int nAuraDmgVal;
    int32_t nAuraStatValue;
    D2SkillsTxt* pDVar3;
    short int nAuraStat;
    D2UnitStrc* pUnit = UNIT::Player::GetPlayerUnit_UI();
    if (!pUnit) {
      return 0;
    }

    int nTotalDmg = 0;
    int nStateIdx = 0;
    if (0 >= (short int)sgptDataTable->nAllStatesDataTblFlag0x04Size) {
      return nTotalDmg;
    }

    do {
      eD2States eState;
      eState = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, (int)sgptDataTable->pAllStatesDataTblFlag0x04[nStateIdx].nStateId);
      if (eState != STATE_none) {
        pStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, (int)sgptDataTable->pAllStatesDataTblFlag0x04[nStateIdx].nStateId);
        if (pStatList) {
          eSkill = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, UNITSTAT_modifierlist_skill, 0);
          if ((int)eSkill > 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount) {
            pDVar3 = sgptDataTable->pTxtSkills + eSkill;
            if (pDVar3) {
              nStateCount = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, UNITSTAT_modifierlist_level, 0);
              if (nStateCount > 0 && pDVar3->prgdam == '\x01') {
                nAuraStat = pDVar3->aurastat[0];
                if (nAuraStat >= 0 && (int)nAuraStat < sgptDataTable->nTxtItemStatCostSize) {
                  nAuraDmgVal = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, (int)nAuraStat, 0);
                  if (nAuraDmgVal > 0) {
                    nAuraStatValue = DataTbls::TXT_Skills_GetSkillRange(eSkill, nStateCount);
                    nTotalDmg += nAuraStatValue * nAuraDmgVal;
                  }
                }
              }
            }
          }
        }
      }

      nStateIdx++;
    } while (nStateIdx < (short int)sgptDataTable->nAllStatesDataTblFlag0x04Size);

    return nTotalDmg;
}

int __stdcall SKILLDESC_AccumulateAuraBonusDmg(D2UnitStrc * pUnit, int * pnMinDmgAcc, int * pnMaxDmgAcc, uint32_t * pdwElemColorOut) {
    D2StatListExStrc* pStatList;
    eD2Skills eSkill;
    int nSkillLevel;
    int nAuraStatValue;
    D2SkillDescTxt* pSkillDesc;
    int32_t nCalcMin;
    uint32_t nCalcResult;
    uint8_t byElemType;
    short int nAuraStat;
    D2SkillsTxt* pSkillsTxt;
    int nStateIdx = 0;
    if ((short int)sgptDataTable->nAllStatesDataTblFlag0x04Size <= 0) {
      return 1;
    }

    do {
      eD2States eState;
      eState = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, (int)sgptDataTable->pAllStatesDataTblFlag0x04[nStateIdx].nStateId);
      if (eState != STATE_none) {
        pStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, (int)sgptDataTable->pAllStatesDataTblFlag0x04[nStateIdx].nStateId);
        if (pStatList) {
          eSkill = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, UNITSTAT_modifierlist_skill, 0);
          if ((int)eSkill > 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount) {
            pSkillsTxt = sgptDataTable->pTxtSkills;
            if (pSkillsTxt + eSkill) {
              nSkillLevel = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, UNITSTAT_modifierlist_level, 0);
              if (nSkillLevel > 0) {
                nAuraStat = pSkillsTxt[eSkill].aurastat[0];
                if (nAuraStat >= 0 && (int)nAuraStat < sgptDataTable->nTxtItemStatCostSize) {
                  nAuraStatValue = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList, (int)nAuraStat, 0);
                  if (nAuraStatValue > 0) {
                    pSkillDesc = DataTbls::GetSkillDescription(eSkill);
                    if (!pSkillDesc) {
                      nCalcMin = D2Common::Skills::SERVER_MinDamage(pUnit, eSkill, nSkillLevel, 1);
                      *pnMinDmgAcc += nCalcMin >> 8;
                      nCalcMin = D2Common::Skills::SERVER_MaxDamage(pUnit, eSkill, nSkillLevel, 1);
                      *pnMaxDmgAcc += nCalcMin >> 8;
                    } else {
                      if (nAuraStatValue > 1) {
                        if (nAuraStatValue >= 3) {
                          nAuraStatValue = 3;
                        }
                      } else {
                        nAuraStatValue = 1;
                      }

                      nCalcResult = D2Common::Skills::SKILLS_EvalDescCalcBytecode(pUnit, *(uint32_t*)(pSkillDesc->dmelem + nAuraStatValue * 4), eSkill, nSkillLevel);
                      *pnMinDmgAcc += nCalcResult;
                      nCalcResult = D2Common::Skills::SKILLS_EvalDescCalcBytecode(pUnit, (uint32_t)pSkillDesc->dmmin[nAuraStatValue + 2], eSkill, nSkillLevel);
                      *pnMaxDmgAcc += nCalcResult;
                      byElemType = pSkillDesc->dmelem[nAuraStatValue - 1];
                      if (byElemType > 0 && byElemType < 0xd) {
                        nCalcResult = SKILLDESC_ElemTypeToColorIndex((eD2ElementalDamageTypeDWORD)byElemType);
                        *pdwElemColorOut = nCalcResult;
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }

      nStateIdx++;
    } while (nStateIdx < (short int)sgptDataTable->nAllStatesDataTblFlag0x04Size);

    return 1;
}

static void __stdcall SKILLDESC_CalcSkillElemDamage(D2UnitStrc * pUnit, int * pnMinDmgAcc, int * pnMaxDmgAcc, int32_t * pdwColorIdx, short * pSkillDescTxt, int32_t nSkillLevel) {
    int32_t nMinDmgRaw;
    int nMaxDmg;
    int iVar1;
    if ((char)pSkillDescTxt[0xee] == '\x05') {
      int32_t nSynergyMul;
      nSynergyMul = D2Common::Skills::SERVER_Synergy1(pUnit, (int)*pSkillDescTxt, nSkillLevel, 1);
      *pdwColorIdx = 2;
      nMinDmgRaw = D2Common::Skills::SERVER_MinDamage(pUnit, (int)*pSkillDescTxt, nSkillLevel, 1);
      iVar1 = nSynergyMul * nMinDmgRaw;
      nMinDmgRaw = D2Common::Skills::SERVER_MaxDamage(pUnit, (int)*pSkillDescTxt, nSkillLevel, 1);
      nMaxDmg = nMinDmgRaw * nSynergyMul;
    } else {
      iVar1 = D2Common::Skills::SERVER_MinDamage(pUnit, (int)*pSkillDescTxt, nSkillLevel, 1);
      nMaxDmg = D2Common::Skills::SERVER_MaxDamage(pUnit, (int)*pSkillDescTxt, nSkillLevel, 1);
    }

    iVar1 >>= 8;
    nMaxDmg >>= 8;
    if (pdwColorIdx) {
      switch ((char)pSkillDescTxt[0xee]) {
        case '\x01':
          *pdwColorIdx = 1;
        *pnMinDmgAcc += iVar1;
        *pnMaxDmgAcc += nMaxDmg;
        return;
        case '\x02':
          *pdwColorIdx = 9;
        *pnMinDmgAcc += iVar1;
        *pnMaxDmgAcc += nMaxDmg;
        return;
        case '\x03':

        case '\x04':
          *pdwColorIdx = 3;
        *pnMinDmgAcc += iVar1;
        *pnMaxDmgAcc += nMaxDmg;
        return;
        case '\x05':
          *pdwColorIdx = 2;
      }
    }

    *pnMinDmgAcc += iVar1;
    *pnMaxDmgAcc += nMaxDmg;
}

