      Fog::File::CONTAINER_InitializeBuffer(wszSmallBuf, 2, 0x20, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
      /* LPCSTR param_2 for wsprintfA */ /* LPSTR param_1 for wsprintfA */ wsprintfA(szFormatBuf, "%d-%d", nCalcA, nCalcB);
