      SKILLDESC_FormatDecimalWithStrings(wDescTextA, wDescTextB, nCalcB, nCalcA, pwszOutput, 1);
      return 1;
      case 0x3d:
        if (!nCalcB) {
          nCalcB = 10;
        }
      SKILLDESC_FormatDecimalWithStrings(wDescTextA, wDescTextB, nCalcB, nCalcA, pwszOutput, 0);
      return 1;
      case 0x3e:
        SKILLDESC_FormatMinMaxRangeLabelsFirst(nCalcA, nCalcB, pwszOutput, 0, wDescTextB, wDescTextA);
      return 1;
      case 0x3f:
        SKILLDESC_DescLine3F_SignedPctRange(nCalcA, wDescTextB, 1, 1, wDescTextA, pwszOutput);
      return 1;
      case 0x40:
        SKILLDESC_DescLine40_DecimalLabel(wDescTextB, nCalcA, 1, wDescTextA, pwszOutputLocal, nCalcB);
      return 1;
      case 0x41:
        SKILLDESC_DescLine41_AppendStrings(wDescTextA, pwszOutput, wDescTextB);
