      return 1;
      case 0x43:
        SKILLDESC_DescLine3F_SignedPctRange(nCalcA, wDescTextB, 1, 0, wDescTextA, pwszOutput);
      return 1;
      case 0x44:
        SKILLDESC_FormatValueTwoStrings(nCalcA, wDescTextA, wDescTextB, 0, pwszOutput);
      return 1;
      case 0x45:
        SKILLDESC_DescLine45_DecimalLabel(wDescTextB, 0, 0, wDescTextA, pwszOutput, nCalcA);
      return 1;
      case 0x46:
        pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(wDescTextA);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      SKILLDESC_FormatSignedValue(nCalcA, wDescTextB, 1, pwszOutput);
      return 1;
      case 0x47:
        if (wDescTextA == 0x1506) {
          return 0;
        }
      if (wDescTextB == 0x1506) {
        return 0;
      }

      Fog::File::CONTAINER_InitializeBuffer(wszLargeBuf, 2, 100, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
      nSigned = nCalcA;
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(wDescTextB);
      D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(100, wszLargeBuf, pWszLocale, nSigned);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(wDescTextA);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(0xf9d);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(0xf9b);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      goto append_formatted_line;
      case 0x48:
        if (!nCalcA) {
          return 0;
        }
      if ((int)nCalcB <= 0) {
        return 0;
      }

      Fog::File::CONTAINER_InitializeBuffer(wszSmallBuf, 2, 0x20, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
      SKILLDESC_FormatIntValue(wszSmallBuf, 1, nCalcA);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, wszSmallBuf);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(4000);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      /* LPCSTR param_2 for wsprintfA */ /* LPSTR param_1 for wsprintfA */ wsprintfA(szFormatBuf, "%d", nCalcB);
      goto append_calcb_and_texta;
      case 0x49:
        if (!nCalcA) {
          return 0;
        }
      if ((int)nCalcB <= 0) {
        return 0;
      }

      Fog::File::CONTAINER_InitializeBuffer(wszSmallBuf, 2, 0x20, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
      /* LPCSTR param_2 for wsprintfA */ /* LPSTR param_1 for wsprintfA */ wsprintfA(szFormatBuf, "%d", nCalcA);
      D2Lang::UTF8_ConvertToWideChar(wszSmallBuf, szFormatBuf, 0x20);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, wszSmallBuf);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(4000);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      /* LPCSTR param_2 for wsprintfA */ /* LPSTR param_1 for wsprintfA */ wsprintfA(szFormatBuf, "%d", nCalcB);
      append_calcb_and_texta:
      D2Lang::UTF8_ConvertToWideChar(wszSmallBuf, szFormatBuf, 0x20);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, wszSmallBuf);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(0xf9b);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(wDescTextA);
      goto append_and_newline;
      case 0x4a:
        if (wDescTextA == 0x1506) {
          return 0;
        }
      Fog::File::CONTAINER_InitializeBuffer(wszLargeBuf, 2, 100, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
      nSigned = nCalcA;
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(wDescTextA);
      D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(100, wszLargeBuf, pWszLocale, nSigned);
      goto append_formatted_line;
      case 0x4b:
        if (wDescTextA == 0x1506) {
          return 0;
        }
      Fog::File::CONTAINER_InitializeBuffer(wszLargeBuf, 2, 100, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
      nSigned = nCalcA;
      uVar2 = nCalcB;
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(wDescTextA);
      D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(100, wszLargeBuf, pWszLocale, nSigned, uVar2);
      append_formatted_line:
      pWszLocale = wszLargeBuf;
      append_and_newline:
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
      pWszLocale = D2Lang::StrTable::strtable::GetLocaleString(0xf9e);
      D2Lang::Unicode::UNISYS::AppendToBuffer(pwszOutput, pWszLocale);
